427	// Strict decoding of committed circuit records.
428	//
429	// A circuit record in data.json must name each of name, version, constraints,
430	// public_inputs, private_inputs, frozen and description exactly once, with
431	// the exact JSON type the writer emits (string / integer / integer / integer
432	// / integer / boolean / string). A missing key, a null, a wrong type or a
433	// repeated key is data corruption and refuses the whole directory read: a
434	// missing or null frozen flag must not silently read as false (turning a
435	// frozen version back into an editable draft), and a repeated key must not
436	// resolve to its last value. An explicit 0, false or "" is an ordinary value
437	// and stays legal. The definition member remains the one optional field: it
438	// may be absent or null (the legacy counts-only state); when present it goes
439	// through the strict persistDefinition decoder.
440	//
441	// The name field carries one rule beyond shape: its raw JSON string token
442	// must denote its value exactly — valid UTF-8 in the literal portions and no
443	// unpaired \uXXXX surrogate escapes (checkStoredStringEncoding). Both damage
444	// shapes decode to U+FFFD replacement characters under encoding/json, which
445	// would rename the circuit on read; they are data corruption, and the whole
446	// directory read is refused. Only the name is judged this way; every other
447	// field keeps the ordinary decoding rules.
448	//
449	// Only shape is judged here. The domain rules (non-blank name, positive
450	// version and constraint count, non-negative input counts) keep being
451	// re-checked by validateEnvelope.
452	
453	var persistCircuitFields = []string{
454		"name", "version", "constraints", "public_inputs", "private_inputs",
455		"frozen", "description", "definition",
456	}
457	
458	// storedRecordShape is the shared strict-JSON rule set (definition_schema.go)
459	// tagged for committed data: every structural failure in a stored circuit
460	// record is data corruption, never a bad request.
461	var storedRecordShape = jsonShape{fail: corruptf}
462	
463	func (c *persistCircuit) UnmarshalJSON(raw []byte) error {
464		const what = "stored circuit record"
465		if string(bytes.TrimSpace(raw)) == "null" {
466			return corruptf("%s must be a JSON object, not null", what)
467		}
468		members, err := strictCircuitObject(raw, what)
469		if err != nil {
470			return err
471		}
472	
473		var out persistCircuit
474	
475		requireString := func(key string, dst *string) error {
476			r, err := storedRecordShape.require(members, key, what)
477			if err != nil {
478				return err
479			}
480			v, err := storedRecordShape.string(r, what+" field "+strconv.Quote(key))
481			if err != nil {
482				return err
483			}
484			*dst = v
485			return nil
486		}
487		requireInt := func(key string, dst *int) error {
488			r, err := storedRecordShape.require(members, key, what)
489			if err != nil {
490				return err
491			}
492			v, err := storedRecordShape.int(r, what+" field "+strconv.Quote(key))
493			if err != nil {
494				return err
495			}
496			*dst = v
497			return nil
498		}
499	
500		if err := requireString("name", &out.Name); err != nil {
501			return err
502		}
503		// The name is the version's identity and must read back as the exact
504		// value that was committed. encoding/json silently rewrites both invalid
505		// UTF-8 bytes and unpaired \uXXXX surrogate escapes to U+FFFD, so the
506		// decoded string alone cannot tell a damaged name apart from one that
507		// legitimately contains "�". Judge the raw JSON token instead.
508		if err := checkStoredStringEncoding(members["name"], what+` field "name"`, "committed name"); err != nil {
509			return err
510		}
511		if err := requireInt("version", &out.Version); err != nil {
512			return err
513		}
514		if err := requireInt("constraints", &out.Constraints); err != nil {
515			return err
516		}
517		if err := requireInt("public_inputs", &out.PublicInputs); err != nil {
518			return err
519		}
520		if err := requireInt("private_inputs", &out.PrivateInputs); err != nil {
521			return err
522		}
523		frozenRaw, err := storedRecordShape.require(members, "frozen", what)
524		if err != nil {
525			return err
526		}
527		out.Frozen, err = storedRecordShape.bool(frozenRaw, what+" field "+strconv.Quote("frozen"))
528		if err != nil {
529			return err
530		}
531		if err := requireString("description", &out.Description); err != nil {
532			return err
533		}
534	
535		// definition is the only optional member: absent or null both mean the
536		// counts-only legacy state.
537		if defRaw, present := members["definition"]; present {
538			if string(bytes.TrimSpace(defRaw)) != "null" {
539				var def persistDefinition
540				if err := json.Unmarshal(defRaw, &def); err != nil {
541					var se StoreError
542					if errors.As(err, &se) {
543						return err // already reported as data corruption
544					}
545					return corruptf("%s field %s is not a valid constraint definition: %v", what, strconv.Quote("definition"), err)
546				}
547				out.Definition = &def
548			}
549		}
550	
551		*c = out
552		return nil
553	}
