690	// Store is a persistent workbench backed by one local data directory.
691	//
692	// All operations are safe for concurrent use by multiple goroutines and by
693	// several processes pointed at the same directory: an in-process mutex plus a
694	// process-shared flock serialize commits, and every commit is an atomic
695	// temp-file/fsync/rename replacement. Open the directory with Open and call
696	// Close when done.
697	type Store struct {
698		dir  string
699		mu   sync.Mutex
700		lock *os.File
701	
702		data envelope
703	}
704	
705	// resolveDataDir turns the Open argument into the absolute physical
706	// directory the store will be permanently pinned to.
707	//
708	// The argument is resolved exactly the way the kernel reaches it on an
709	// open(2) — relative components anchored to the process's current working
710	// directory at Open time, one component at a time, every symlink expanded at
711	// the position where the walk meets it. No lexical Clean is applied first:
712	// filepath.Abs/Clean would fold "entry/.." before the symlink was ever
713	// examined, so a ".." standing after a symlink pops the link's resolved
714	// target rather than the link's own spelling, and a/link/../x cannot be made
715	// to name a/x and select another data directory. Any trailing segment that
716	// does not exist yet (a data directory to be created by Open, or a
717	// not-yet-existing parent) is appended verbatim to the resolved physical
718	// prefix, and MkdirAll creates it beneath that prefix; a ".." after such a
719	// missing component cannot be walked faithfully (the kernel reports ENOENT
720	// there instead of folding the literal path) and fails the resolution. A
721	// dangling entry link — the entry itself is a symlink whose target does not
722	// exist — resolves through the link target's spelling and is created there.
723	func resolveDataDir(dir string) (string, error) {
724		resolved, err := resolveExistingPrefix(dir)
725		if err != nil {
726			return "", err
727		}
728		if !filepath.IsAbs(resolved) {
729			// The walk itself stayed relative to the Open-time working directory;
730			// only now, after every symlink has been expanded and every ".."
731			// popped in walk order, anchor the result absolutely for pinning.
732			resolved, err = filepath.Abs(resolved)
733			if err != nil {
734				return "", err
735			}
736		}
737		return resolved, nil
738	}
739	
740	// maxDataDirLinks bounds symlink expansion while resolving the data
741	// directory, matching the kernel's ELOOP guard: a link cycle must fail Open
742	// rather than loop forever.
743	const maxDataDirLinks = 255
744	
745	// resolveExistingPrefix walks path the way a kernel path walk reaches it,
746	// accepting both absolute and Open-cwd-relative paths. Symlinks are expanded
747	// inline where the walk meets them and ".." pops the directory the walk is
748	// actually standing in (a link target, not the link spelling). Unlike
749	// filepath.EvalSymlinks the walk tolerates a missing tail: at the first
750	// component that cannot be Lstat'd, that component and the remaining literal
751	// components are appended to the resolved prefix so Open can create the chain
752	// with MkdirAll — unless the remainder contains "..", which could not be
753	// resolved against a non-existent entry and is an error.
754	func resolveExistingPrefix(path string) (string, error) {
755		volLen := len(filepath.VolumeName(path))
756		pathSeparator := string(os.PathSeparator)
757		if volLen < len(path) && os.IsPathSeparator(path[volLen]) {
758			volLen++
759		}
760		vol := path[:volLen] // "/" (or a drive/UNC root elsewhere); "" when relative
761		dest := vol
762		linksWalked := 0
763		for start, end := volLen, volLen; start < len(path); start = end {
764			for start < len(path) && os.IsPathSeparator(path[start]) {
765				start++
766			}
767			end = start
768			for end < len(path) && !os.IsPathSeparator(path[end]) {
769				end++
770			}
771			if end == start {
772				break
773			}
774			comp := path[start:end]
775			if comp == "." {
776				continue
777			}
778			if comp == ".." {
779				// Pop what the walk has actually reached; symlinks have already
780				// been expanded into dest, so this removes the target, never the
781				// link spelling.
782				r := -1
783				for i := len(dest) - 1; i >= volLen; i-- {
784					if os.IsPathSeparator(dest[i]) {
785						r = i
786						break
787					}
788				}
789				if r < volLen || dest[r+1:] == ".." {
790					if len(dest) > volLen {
791						dest += pathSeparator
792					}
793					dest += ".."
794				} else {
795					dest = dest[:r]
796				}
797				continue
798			}
799	
800			if len(dest) > len(filepath.VolumeName(dest)) && !os.IsPathSeparator(dest[len(dest)-1]) {
801				dest += pathSeparator
802			}
803			dest += comp
804	
805			fi, err := os.Lstat(dest)
806			if err != nil {
807				if !os.IsNotExist(err) {
808					return "", err
809				}
810				// Missing tail: append the remainder literally, refusing a
811				// remainder containing ".." (unresolvable against this absent
812				// entry), and let MkdirAll create the chain.
813				for r := end; r < len(path); {
814					for r < len(path) && os.IsPathSeparator(path[r]) {
815						r++
816					}
817					s := r
818					for r < len(path) && !os.IsPathSeparator(path[r]) {
819						r++
820					}
821					switch path[s:r] {
822					case "", ".":
823					case "..":
824						return "", fmt.Errorf("cannot resolve %q: %q does not exist and is followed by a parent reference", path, comp)
825					default:
826						dest += pathSeparator + path[s:r]
827					}
828				}
829				return filepath.Clean(dest), nil
830			}
831			if fi.Mode()&os.ModeSymlink == 0 {
832				if !fi.Mode().IsDir() && end < len(path) {
833					return "", fmt.Errorf("cannot resolve %q: %q is not a directory", path, comp)
834				}
835				continue
836			}
837			linksWalked++
838			if linksWalked > maxDataDirLinks {
839				return "", fmt.Errorf("cannot resolve %q: too many symlinks", path)
840			}
841			link, err := os.Readlink(dest)
842			if err != nil {
843				return "", err
844			}
845			// Expand the link exactly at the walk position: the still-queued
846			// components (including any "..") continue from the target rather
847			// than from the link spelling.
848			path = link + path[end:]
849			switch {
850			case len(link) > 0 && os.IsPathSeparator(link[0]):
851				volLen = 1
852				vol = path[:1]
853				dest = vol
854				end = 1
855			default:
856				if v := filepath.VolumeName(link); v != "" {
857					if len(link) > len(v) && os.IsPathSeparator(link[len(v)]) {
858						v += string(os.PathSeparator)
859					}
860					volLen = len(v)
861					vol = v
862					dest = vol
863					end = volLen
864					break
865				}
866				// Relative link: it names a path from the directory holding the
867				// link, which is dest without the link's own component.
868				r := -1
869				for i := len(dest) - 1; i >= volLen; i-- {
870					if os.IsPathSeparator(dest[i]) {
871						r = i
872						break
873					}
874				}
875				if r < volLen {
876					dest = vol
877				} else {
878					dest = dest[:r]
879				}
880				end = 0
881			}
882		}
883		return filepath.Clean(dest), nil
884	}
885	
886	// Open opens (creating if needed) the workbench data in dir. If the
887	// directory does not exist it is created. Existing committed data is loaded
888	// and fully validated before Open returns; on a corrupt, truncated or
889	// unsupported-format file Open returns an error wrapping ErrDataCorrupt and
890	// leaves every file in the directory untouched.
891	//
892	// dir is resolved against the process's current working directory at Open
893	// time and pinned for the store's lifetime: a relative path such as
894	// "bench-data" names one fixed directory from the moment Open succeeds, and
895	// later working-directory changes never redirect the store's reads, writes,
896	// lock or Dir to another location.
897	//
898	// The pinning is to the actual directory opened, not to the literal path
899	// spelling: symlinks already present in the file system — whether dir itself
900	// is a link or one of its parent directories is — are resolved segment by
901	// segment at Open time, and Dir reports the resulting absolute physical
902	// directory. Repointing or removing an entry link afterwards never moves the
903	// store: queries, commits, the lock file and compiled-artifact bindings keep
904	// using the original directory even after the link changes or vanishes. A
905	// ".." following a symlink is resolved the way the kernel walk reaches it
906	// (the already-resolved link target is popped), never by lexical folding of
907	// the literal path, so it cannot select a different data directory. A
908	// not-yet-existing data directory named through a valid (possibly
909	// symlinked) parent is created under the parent's physical location. Paths
910	// to constraint definitions and input files passed to individual operations
911	// are not pinned this way — they keep being resolved against the caller's
912	// working directory at call time.
913	func Open(dir string) (*Store, error) {
914		if dir == "" {
915			return nil, invalidf("data directory must not be empty")
916		}
917		// Resolve and pin the physical location now, before anything else can
918		// change. resolveDataDir walks the argument the way the kernel reaches
919		// it — relative to the process working directory at Open time, symlinks
920		// expanded segment by segment in walk order and ".." popped in place — so
921		// a later chdir, a repointed or deleted entry link, or a ".." sitting
922		// after a symlink cannot move reads, writes, the lock or Dir onto another
923		// directory. The result is absolute and names the real directory opened.
924		dir, err := resolveDataDir(dir)
925		if err != nil {
926			return nil, fmt.Errorf("cannot resolve data directory %q: %w", dir, err)
927		}
928		if err := os.MkdirAll(dir, 0o755); err != nil {
929			return nil, fmt.Errorf("cannot create data directory %q: %w", dir, err)
930		}
931		lockPath := filepath.Join(dir, dirLockFile)
932		lock, err := os.OpenFile(lockPath, os.O_RDWR|os.O_CREATE, 0o644)
933		if err != nil {
934			return nil, fmt.Errorf("cannot open lock file in %q: %w", dir, err)
935		}
936		// Serialize against other processes while we read / validate.
937		if err := lockExclusive(lock); err != nil {
938			lock.Close()
939			return nil, fmt.Errorf("cannot lock data directory %q: %w", dir, err)
940		}
941	
942		s := &Store{dir: dir, lock: lock}
943		if err := s.loadLocked(); err != nil {
944			unlockLock(lock)
945			lock.Close()
946			return nil, err
947		}
948		// The lock is taken again per operation; holding it for the store's
949		// lifetime would forbid two open handles on one directory.
950		if err := unlockLock(lock); err != nil {
951			lock.Close()
952			return nil, fmt.Errorf("cannot release open lock on %q: %w", dir, err)
953		}
954		return s, nil
955	}
956	
957	// Close releases the directory lock. It does not discard committed data.
958	func (s *Store) Close() error {
959		s.mu.Lock()
960		defer s.mu.Unlock()
961		if s.lock == nil {
962			return nil
963		}
964		var first error
965		if err := unlockLock(s.lock); err != nil {
966			first = err
967		}
968		if err := s.lock.Close(); err != nil && first == nil {
969			first = err
970		}
971		s.lock = nil
972		return first
973	}
