975	// Dir reports the data directory backing the store.
976	func (s *Store) Dir() string { return s.dir }
977	
978	func (s *Store) dataPath() string { return filepath.Join(s.dir, dirDataFile) }
979	func (s *Store) tmpPath() string  { return filepath.Join(s.dir, dirTmpFile) }
