	if _, err := s.SubmitJob(boundProveJob("j-bound", "c", 1, hash)); err != nil {
		t.Fatal(err)
	}
	if _, err := s.SubmitJob(boundProveJob("j-plain", "c", 1, "")); err != nil {
		t.Fatal(err)
	}
	if err := s.Close(); err != nil {
		t.Fatal(err)
	}
